import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, m = map(int, sys.stdin.readline().split())
        if m == 0:
            print(0)
        else:
            total = n * (n + 1) // 2
            max_f = total - (n - m) * (n - m + 1) // 2
            print(max_f)

solve()
